def resample_s16(data: bytes, src_rate: int, channels: int) -> NDArray[np.float32]:
    """Resample s16le PCM to 16 kHz mono. Rust when available, numpy fallback."""
    if _HAS_RUST_RESAMPLE and _rs_resample is not None:
        return _rs_resample(data, src_rate, channels)
    samples = np.frombuffer(data, dtype=np.int16).astype(np.float32) * (1.0 / 32768.0)
    if channels > 1:
        samples = samples.reshape(-1, channels).mean(axis=1)
    if src_rate != _TARGET_SR and src_rate > 0:
        n_out = int(len(samples) * _TARGET_SR / src_rate)
        if n_out == 0:
            return np.empty(0, dtype=np.float32)
        indices = np.linspace(0, len(samples) - 1, n_out)
        samples = np.interp(indices, np.arange(len(samples)), samples).astype(np.float32)
    return samples

