def append(self, pcm_bytes: bytes, t1_audio: float) -> None:
        if not pcm_bytes:
            return
        samples = np.frombuffer(pcm_bytes, dtype=np.int16).astype(np.float32) * (1.0 / 32768.0)
        if samples.size == 0:
            return
        duration = samples.size / _TARGET_SR
        chunk = _AudioChunk(pcm=samples, t0=t1_audio - duration, t1=t1_audio)
        self._chunks.append(chunk)
        self._evict(t1_audio)
